      if (!targets.length) return fail(tr(`No member of run ${run.id} matches ${roles?.join(", ")}.`, `\u8FD0\u884C ${run.id} \u4E2D\u6CA1\u6709\u6210\u5458\u5339\u914D ${roles?.join(", ")}\u3002`));
