      agentId: external_exports.string().optional().describe(tr("The member's agent id, when several members share a role", "\u6210\u5458\u7684 agent id\uFF08\u591A\u4E2A\u6210\u5458\u5171\u7528\u4E00\u4E2A\u89D2\u8272\u65F6\uFF09")),
